function check(ok, where) { checks++; if (!ok) throw Error(where); }
function sha(x) { return crypto.createHash('sha256').update(x).digest('hex'); }
function raw(path) { if (!seen.has(path)) { const st=fs.lstatSync(path); check(st.isFile() && !st.isSymbolicLink(), 'regular-file '+path); seen.set(path,fs.readFileSync(path)); } return seen.get(path); }
function read(path) { return JSON.parse(raw(path).toString('utf8')); }
