for(const s of p.sources) {
  desc(s.carrier);
  const locked=at(lock,s.carrier.input_lock_pointer);
  check(locked.path===s.carrier.path && locked.bytes===s.carrier.bytes && locked.sha256===s.carrier.sha256,'locked carrier '+s.ref_slug);
  const carrier=read(s.carrier.path), original=at(carrier,s.raw_field);
  check(typeof original==='string','raw string '+s.ref_slug);
  check(s.raw_field===s.raw_field_binding.json_pointer,'raw pointer '+s.ref_slug);
  check(Buffer.byteLength(original,'utf8')===s.raw_field_binding.utf8_bytes && sha(original)===s.raw_field_binding.sha256,'raw field binding '+s.ref_slug);
