  check(sha(held)===s.source_body_sha256 && sha(held)===s.source_content_sha256 && Buffer.byteLength(held,'utf8')===s.held_content_bytes,'held content hashes '+s.ref_slug);
  const fr=s.historical_finalization_record; desc(fr.carrier); const finalization=read(fr.carrier.path), record=at(finalization,fr.row_pointer);
