  check(s.excerpt===record.support_excerpt && s.excerpt===at(finalization,fr.excerpt_pointer),'historical excerpt '+s.ref_slug);
  check(sha(s.excerpt)===s.excerpt_sha256 && s.excerpt_sha256===record.support_excerpt_sha256,'excerpt hashes '+s.ref_slug);
  check(s.excerpt.trim().split(/\s+/u).length===s.excerpt_word_count && s.excerpt_word_count<=25 && Array.from(s.excerpt).length===s.excerpt_codepoints && s.excerpt_codepoints<=1000 && s.excerpt_literal_match===true,'excerpt budget '+s.ref_slug);
  exactSpan(held,s.excerpt,s.excerpt_span_in_held_source,s.ref_slug);
  for(const [field,pointerKey] of [['registered_role','registered_role_pointer'],['hypothesis_or_scope','scope_pointer'],['transfer_boundary_preserved','excluded_transfer_pointer']]) check(fr[field]===at(finalization,fr[pointerKey]),'local record field '+s.ref_slug+' '+field);
