  check(request.source_url===requestRaw.request_url,'request URL '+s.ref_slug);
  const web=s.separate_web_corroboration;
  if(web.available) {
    supplementary++; desc(web.carrier); const result=at(read(web.carrier.path),web.result_pointer);
    check(Buffer.byteLength(result,'utf8')===web.result_utf8_bytes && sha(result)===web.result_sha256,'web result '+s.ref_slug);
    const candidates=result.split(/-{20,}\n/).filter(t=>t.split('\n')[0].includes(web.source_url)); check(candidates.length===1,'unique web segment '+s.ref_slug);
    const segment=candidates[0]; check(segment.split('\n')[0]===web.named_segment_heading,'segment heading '+s.ref_slug);
    check(Buffer.byteLength(segment,'utf8')===web.raw_segment_utf8_bytes && sha(segment)===web.raw_segment_sha256,'raw segment '+s.ref_slug);
    exactSpan(result,segment,web.named_segment_span_in_result,'web segment '+s.ref_slug);
    const body=segment.replace(/\s+/g,' ').trim().replaceAll('\\Gamma','Γ');
    check(body===oldBody && sha(body)===web.transformed_content_sha256 && Buffer.byteLength(body,'utf8')===web.transformed_content_bytes && web.replays_recovery1_held_text_exactly===true,'web recipe replay '+s.ref_slug);
    check(web.excerpt===s.excerpt && sha(web.excerpt)===web.excerpt_sha256 && web.excerpt_literal_match===true && web.selected_as_recovery3_source===false && web.page_authentication_performed===false,'web caveat '+s.ref_slug);
    exactSpan(body,web.excerpt,web.excerpt_span_in_separate_held_text,'web excerpt '+s.ref_slug);
  } else check(s.ref_slug==='P31-S09' && web.same_raw_carrier===true && web.same_held_source_sha256===s.source_body_sha256 && held===oldBody,'S09 same source not independent web');
  results.push({ref_slug:s.ref_slug,held_bytes:Buffer.byteLength(held,'utf8'),excerpt_words:s.excerpt_word_count,selected_recipe_replayed:true,supplementary_web_replayed:web.available,claim_bindings:4});
